#!/usr/bin/env python3
"""
CKD Lab Data Unit Harmonization Script

This script harmonizes clinical lab data by:
1. Removing rows with missing values
2. Handling scientific notation and comma-decimal issues
3. Converting values outside physiological ranges to standard US units
4. Rounding all values to 2 decimal places
"""

import pandas as pd
import numpy as np
import re

# Read the data
input_file = '/root/environment/data/ckd_lab_data.csv'
output_file = '/root/ckd_lab_data_harmonized.csv'

print("Loading data...")
df = pd.read_csv(input_file, dtype=str)
print(f"Original data shape: {df.shape}")

# Step 1: Check for missing values and drop rows with any missing values
print("\nStep 1: Removing rows with missing values...")
initial_rows = len(df)
df = df.dropna()
print(f"Rows removed due to missing values: {initial_rows - len(df)}")
print(f"Remaining rows: {len(df)}")

# Step 2: Function to clean and convert numeric values
def clean_numeric(value):
    """
    Clean numeric string values:
    - Handle scientific notation
    - Replace comma with period for decimals
    - Return float
    """
    if pd.isna(value):
        return np.nan

    # Convert to string
    val_str = str(value).strip()

    # Remove surrounding quotes if any
    val_str = val_str.strip('"').strip("'")

    # Replace comma with period (European decimal notation)
    val_str = val_str.replace(',', '.')

    try:
        # Convert to float (handles scientific notation automatically)
        return float(val_str)
    except ValueError:
        return np.nan

print("\nStep 2: Cleaning numeric formats (scientific notation, comma decimals)...")
# Apply cleaning to all columns except patient_id
for col in df.columns:
    if col != 'patient_id':
        df[col] = df[col].apply(clean_numeric)

# Check for any rows that became NaN after conversion
pre_drop = len(df)
df = df.dropna()
print(f"Rows removed after numeric conversion: {pre_drop - len(df)}")
print(f"Remaining rows: {len(df)}")

# Step 3: Define physiological ranges and conversion factors
# Format: (min_normal, max_normal, alt_unit_factor, alt_unit_description)
# alt_unit_factor: multiply by this to convert FROM alternative unit TO US conventional unit
# If value is too HIGH, divide by factor; if too LOW, multiply by factor

# Reference ranges are based on typical clinical values
# Conversion factors are based on standard biochemistry conversions

physiological_ranges = {
    # Kidney Function
