    },
    'Aluminum': {
        'us_unit': 'µg/L',
        'min': 0, 'max': 250,
        'alt_conversions': []
    },
}

def apply_unit_conversion(value, col_name, ranges_dict):
    """
    Apply unit conversion if value is outside physiological range.
    """
    if pd.isna(value) or col_name not in ranges_dict:
        return value

    config = ranges_dict[col_name]
    min_val = config['min']
    max_val = config['max']

    # If value is within range, no conversion needed
    if min_val <= value <= max_val:
        return value

    # Try each conversion
    for conv in config.get('alt_conversions', []):
        factor = conv['factor']
        direction = conv['direction']

        if direction == 'divide':
            # Value might be in a unit that needs dividing
            threshold = conv.get('threshold_high', max_val)
            if value > threshold:
                converted = value / factor
                if min_val <= converted <= max_val:
                    return converted
        elif direction == 'multiply':
            # Value might be in a unit that needs multiplying
            threshold = conv.get('threshold_low', min_val)
            if value < threshold:
                converted = value * factor
                if min_val <= converted <= max_val:
                    return converted

    # If no conversion worked, return original value
    # (it might just be an extreme but valid value)
    return value

print("\nStep 3: Applying unit conversions for out-of-range values...")
conversion_counts = {}

for col in df.columns:
    if col == 'patient_id':
        continue

    original_values = df[col].copy()
    df[col] = df[col].apply(lambda x: apply_unit_conversion(x, col, physiological_ranges))

    # Count how many values were converted
    changed = (original_values != df[col]).sum()
    if changed > 0:
        conversion_counts[col] = changed

print(f"Columns with unit conversions applied:")
for col, count in sorted(conversion_counts.items(), key=lambda x: -x[1]):
    print(f"  {col}: {count} values converted")

print("\nStep 4: Rounding all values to 2 decimal places...")
for col in df.columns:
    if col == 'patient_id':
        # Keep patient_id as integer
        df[col] = df[col].astype(float).astype(int)
    else:
        # Round to 2 decimal places and format
        df[col] = df[col].apply(lambda x: round(x, 2) if pd.notna(x) else x)

# Final check for any remaining issues
print("\nFinal data shape:", df.shape)
print("Columns:", len(df.columns))

# Verify all numeric columns are within expected ranges
print("\nVerifying value ranges for key features:")
verification_features = ['Serum_Creatinine', 'BUN', 'Hemoglobin', 'Glucose', 'Sodium', 'Potassium']
for feat in verification_features:
    if feat in df.columns:
        print(f"  {feat}: min={df[feat].min():.2f}, max={df[feat].max():.2f}")

# Save to CSV with proper formatting
print(f"\nSaving harmonized data to {output_file}...")

# Format all numeric columns to 2 decimal places in the output
def format_value(val, col):
    if col == 'patient_id':
        return str(int(val))
    else:
        return f"{val:.2f}"

# Create formatted output
output_df = df.copy()
for col in output_df.columns:
    if col == 'patient_id':
        output_df[col] = output_df[col].astype(int)
    else:
        output_df[col] = output_df[col].apply(lambda x: f"{x:.2f}")

output_df.to_csv(output_file, index=False)

print("Done!")
print(f"\nSummary:")
print(f"  - Input rows: 2590")
print(f"  - Output rows: {len(df)}")
print(f"  - Columns: {len(df.columns)}")

