        'us_range': (0.2, 15.0),  # mg/dL, CKD can have high values
        'conversions': [
            # µmol/L to mg/dL: divide by 88.4
            # µmol/L normal range: ~45-133, CKD: up to 1500+
            {'condition': lambda x: x > 20, 'operation': lambda x: x / 88.4, 'desc': 'µmol/L to mg/dL'}
        ]
    },
    'BUN': {
        'us_range': (5, 200),  # mg/dL
        'conversions': [
            # mmol/L to mg/dL: multiply by 2.8
            # mmol/L normal: 2.5-7.1, high in CKD
            {'condition': lambda x: x < 5, 'operation': lambda x: x * 2.8, 'desc': 'mmol/L to mg/dL'}
        ]
    },
    'eGFR': {
        'us_range': (0, 150),  # mL/min/1.73m²
        'conversions': []
    },
    'Cystatin_C': {
        'us_range': (0.4, 10.0),  # mg/L
        'conversions': []
    },
    'BUN_Creatinine_Ratio': {
        'us_range': (3, 50),  # ratio
        'conversions': []
    },

    # ELECTROLYTES
    'Sodium': {
        'us_range': (110, 170),  # mEq/L (same as mmol/L)
        'conversions': []
    },
    'Potassium': {
        'us_range': (2.0, 9.0),  # mEq/L (same as mmol/L)
        'conversions': []
    },
    'Chloride': {
        'us_range': (70, 140),  # mEq/L
        'conversions': []
    },
    'Bicarbonate': {
        'us_range': (5, 45),  # mEq/L
        'conversions': []
    },
    'Anion_Gap': {
        'us_range': (0, 40),  # mEq/L
        'conversions': []
    },

    # MINERALS
    'Magnesium': {
        'us_range': (1.0, 10.0),  # mg/dL
        'conversions': [
            # mmol/L to mg/dL: multiply by 2.43
            # mmol/L normal: 0.7-1.0
            {'condition': lambda x: x < 1.0, 'operation': lambda x: x * 2.43, 'desc': 'mmol/L to mg/dL'}
        ]
    },
    'Serum_Calcium': {
        'us_range': (5.0, 15.0),  # mg/dL
        'conversions': [
            # mmol/L to mg/dL: multiply by 4.0
            # mmol/L normal: 2.1-2.6
            {'condition': lambda x: x < 4.0, 'operation': lambda x: x * 4.0, 'desc': 'mmol/L to mg/dL'}
        ]
    },
    'Ionized_Calcium': {
