1. Removing rows with missing values
2. Handling scientific notation and comma-decimal issues
3. Converting values outside physiological ranges to standard US units
4. Rounding all values to 2 decimal places
"""

import pandas as pd
import numpy as np

# Read the data
input_file = '/root/environment/data/ckd_lab_data.csv'
output_file = '/root/ckd_lab_data_harmonized.csv'

