        'conversions': []
    },
    'BUN_Creatinine_Ratio': {
        'us_range': (3, 60),
        'conversions': []
    },

    # ELECTROLYTES (typically same units globally)
    'Sodium': {'us_range': (100, 180), 'conversions': []},
    'Potassium': {'us_range': (2.0, 10.0), 'conversions': []},
    'Chloride': {'us_range': (70, 150), 'conversions': []},
    'Bicarbonate': {'us_range': (5, 50), 'conversions': []},
    'Anion_Gap': {'us_range': (0, 45), 'conversions': []},

    # MINERALS
    'Magnesium': {
        # US: mg/dL 1.7-2.4; SI: mmol/L 0.7-1.0
        # mmol/L * 2.43 = mg/dL
