    min_val, max_val = config['us_range']

    # If already in range, return as-is
    if min_val <= value <= max_val:
        return value

    # Try each conversion in order
    for conv in config.get('conversions', []):
        if conv['condition'](value):
            converted = conv['operation'](value)
            # Accept conversion if it brings value closer to valid range
            # even if not perfectly in range
            return converted

    return value

