        # US: mmHg 35-45; SI: kPa 4.7-6.0
        # kPa * 7.5006 = mmHg
        'us_range': (10, 120),
        'conversions': [
            {'condition': lambda x: x < 10, 'operation': lambda x: x * 7.5006}
        ]
    },
    'pO2_Arterial': {
        # US: mmHg 80-100; SI: kPa 10.7-13.3
        'us_range': (25, 600),
        'conversions': [
            {'condition': lambda x: x < 20, 'operation': lambda x: x * 7.5006}
        ]
    },
    'Lactate': {
        # US: mmol/L 0.5-2.2; sometimes mg/dL 4.5-20
        # mg/dL / 9.01 = mmol/L
        'us_range': (0.2, 30.0),
        'conversions': [
            {'condition': lambda x: x > 35, 'operation': lambda x: x / 9.01}
        ]
    },

    # OTHER
    'Beta2_Microglobulin': {'us_range': (0.3, 80.0), 'conversions': []},
    'Aluminum': {'us_range': (0, 300), 'conversions': []},
}

def apply_conversions(value, col_name, configs):
    """Apply unit conversions based on the feature configuration."""
    if pd.isna(value) or col_name not in configs:
        return value

    config = configs[col_name]
    min_val, max_val = config['us_range']

    # If already in range, return as-is
    if min_val <= value <= max_val:
        return value

    # Try each conversion in order
    for conv in config.get('conversions', []):
        if conv['condition'](value):
            converted = conv['operation'](value)
            # Accept conversion if it brings value closer to valid range
            # even if not perfectly in range
            return converted

    return value

print("\nStep 3: Applying unit conversions for out-of-range values...")
conversion_counts = {}

for col in df.columns:
    if col == 'patient_id':
        continue
    original_values = df[col].copy()
    df[col] = df[col].apply(lambda x: apply_conversions(x, col, feature_configs))
    changed = (original_values != df[col]).sum()
    if changed > 0:
        conversion_counts[col] = changed

print("Columns with unit conversions applied:")
for col, count in sorted(conversion_counts.items(), key=lambda x: -x[1]):
    print(f"  {col}: {count} values converted")

# Step 4: Round all values to 2 decimal places
print("\nStep 4: Rounding all values to 2 decimal places...")
for col in df.columns:
    if col == 'patient_id':
        df[col] = df[col].astype(float).astype(int)
    else:
        df[col] = df[col].apply(lambda x: round(x, 2) if pd.notna(x) else x)

# Verification
print("\nFinal data shape:", df.shape)
print("\nVerifying value ranges for key features:")
key_features = [
    ('Serum_Creatinine', 0.2, 20),
    ('BUN', 5, 200),
    ('Hemoglobin', 3, 22),
    ('Glucose', 30, 900),
    ('Sodium', 100, 180),
    ('Potassium', 2, 10),
    ('Total_Cholesterol', 50, 600),
    ('Uric_Acid', 0.5, 25),
    ('Albumin_Serum', 1, 7),
    ('Total_Protein', 2, 15),
]

all_ok = True
for feat, min_v, max_v in key_features:
    if feat in df.columns:
        feat_min = df[feat].min()
        feat_max = df[feat].max()
        below = (df[feat] < min_v).sum()
        above = (df[feat] > max_v).sum()
        status = "OK" if below == 0 and above == 0 else "CHECK"
        if status != "OK":
            all_ok = False
        print(f"  {feat}: [{feat_min:.2f}, {feat_max:.2f}] below={below}, above={above} [{status}]")

# Save the harmonized data
print(f"\nSaving harmonized data to {output_file}...")
output_df = df.copy()
for col in output_df.columns:
    if col == 'patient_id':
        output_df[col] = output_df[col].astype(int)
    else:
        output_df[col] = output_df[col].apply(lambda x: f"{x:.2f}")

output_df.to_csv(output_file, index=False)

print("\nDone!")
print(f"\nSummary:")
print(f"  - Input rows: 2590")
print(f"  - Output rows: {len(df)}")
print(f"  - Columns: {len(df.columns)}")

