#!/usr/bin/env python3
"""
CKD Lab Data Unit Harmonization Script

This script harmonizes clinical lab data by:
1. Removing rows with missing values
2. Handling scientific notation and comma-decimal issues
3. Converting values outside physiological ranges to standard US units
4. Rounding all values to 2 decimal places
"""

import pandas as pd
import numpy as np

# Read the data
input_file = '/root/environment/data/ckd_lab_data.csv'
output_file = '/root/ckd_lab_data_harmonized.csv'

print("Loading data...")
df = pd.read_csv(input_file, dtype=str)
print(f"Original data shape: {df.shape}")

# Step 1: Check for missing values and drop rows with any missing values
print("\nStep 1: Removing rows with missing values...")
initial_rows = len(df)
df = df.dropna()
print(f"Rows removed due to missing values: {initial_rows - len(df)}")
print(f"Remaining rows: {len(df)}")

# Step 2: Function to clean and convert numeric values
def clean_numeric(value):
    """Clean numeric string values: handle scientific notation, comma decimals."""
    if pd.isna(value):
        return np.nan
    val_str = str(value).strip().strip('"').strip("'").replace(',', '.')
    try:
        return float(val_str)
    except ValueError:
        return np.nan

print("\nStep 2: Cleaning numeric formats (scientific notation, comma decimals)...")
for col in df.columns:
    if col != 'patient_id':
        df[col] = df[col].apply(clean_numeric)

pre_drop = len(df)
df = df.dropna()
print(f"Rows removed after numeric conversion: {pre_drop - len(df)}")
print(f"Remaining rows: {len(df)}")

# Step 3: Define conversion rules
# The approach: determine if value is likely in alternate unit based on magnitude,
# then apply conversion. Allow wider ranges for extreme CKD cases.

# Key insight: We need to detect WHICH unit is being used based on the value magnitude
# For each feature, define the expected range in US units and the conversion rules

feature_configs = {
    # KIDNEY FUNCTION
    'Serum_Creatinine': {
        # US: mg/dL, normal 0.5-1.5, CKD can go to 15+ (ESRD can be 25-45+)
        # SI: µmol/L, normal 45-133, CKD can go to 1500+
        # Conversion: µmol/L / 88.4 = mg/dL
        # Values 25-45 are ambiguous but more likely extreme CKD in mg/dL
        # Values >50 are definitely µmol/L
        'us_range': (0.2, 50.0),  # Extended for severe ESRD
        'conversions': [
            {'condition': lambda x: x > 50, 'operation': lambda x: x / 88.4}
        ]
